<?php
session_start(); require_once __DIR__.'/../autenticacao.php'; require_once __DIR__.'/conexaoDB.php'; require_once __DIR__.'/../cabecalho.php'; require_once __DIR__.'/../includes/auditoria.php'; exigirLogin('gerente'); $farmaciaId=(int)$_SESSION['farmacia_id'];
if($_SERVER['REQUEST_METHOD']==='POST'){ $vendaId=(int)($_POST['venda_id']??0);$numero=trim($_POST['numero']??'');$serie=trim($_POST['serie']??'');$chave=trim($_POST['chave_acesso']??'');$protocolo=trim($_POST['protocolo']??'');$status=$_POST['status']??'pendente';$obs=trim($_POST['observacao']??'');$permitidos=array('pendente','emitida','cancelada','erro'); if(!in_array($status,$permitidos,true))$status='pendente'; $stmt=mysqli_prepare($conexao,"SELECT id FROM vendas WHERE id=? AND farmacia_id=?");mysqli_stmt_bind_param($stmt,'ii',$vendaId,$farmaciaId);mysqli_stmt_execute($stmt);if(mysqli_fetch_assoc(mysqli_stmt_get_result($stmt))){$stmt=mysqli_prepare($conexao,'INSERT INTO notas_fiscais (farmacia_id,venda_id,numero,serie,chave_acesso,protocolo,status,observacao) VALUES (?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE numero=VALUES(numero),serie=VALUES(serie),chave_acesso=VALUES(chave_acesso),protocolo=VALUES(protocolo),status=VALUES(status),observacao=VALUES(observacao)');mysqli_stmt_bind_param($stmt,'iissssss',$farmaciaId,$vendaId,$numero,$serie,$chave,$protocolo,$status,$obs);mysqli_stmt_execute($stmt);registrarAuditoria($conexao,'fiscal','venda',$vendaId,'Dados fiscais da venda atualizados');header('Location: fiscal.php?ok=1');exit;}}
$notas=mysqli_query($conexao,"SELECT v.id venda,v.data_venda,v.valor_total,n.id,n.numero,n.serie,n.chave_acesso,n.protocolo,COALESCE(n.status,'pendente') fiscal_status FROM vendas v LEFT JOIN notas_fiscais n ON n.venda_id=v.id WHERE v.farmacia_id=$farmaciaId AND v.status='concluida' ORDER BY v.id DESC LIMIT 100");
?>
<!DOCTYPE html><html lang="pt-BR"><head><?php recursosCabeca('Fiscal'); ?></head><body><?php cabecalho('FarmaCerta - Gerente','gerente','fiscal'); ?><main class="container py-4"><section class="card card-brand rounded-4 p-4 mb-4"><h2 class="h3 fw-bold">CONTROLE FISCAL</h2><p class="mb-0">Registre os dados da NF-e/NFC-e emitida pelo provedor fiscal da farmácia.</p></section><div class="alert alert-info">Este módulo registra número, série, chave e protocolo. A emissão oficial pela SEFAZ exige certificado digital e integração com um provedor/API fiscal.</div><?php if(isset($_GET['ok'])){ ?><div class="alert alert-success">Dados fiscais salvos.</div><?php } ?><section class="card shadow-sm rounded-4 p-3"><div class="table-responsive"><table class="table table-hover align-middle"><thead><tr><th>Venda</th><th>Data</th><th>Valor</th><th>Status fiscal</th><th>Dados</th></tr></thead><tbody><?php while($n=mysqli_fetch_assoc($notas)){ ?><tr><td>#<?php echo $n['venda']; ?></td><td><?php echo date('d/m/Y H:i',strtotime($n['data_venda'])); ?></td><td>R$ <?php echo number_format($n['valor_total'],2,',','.'); ?></td><td><span class="badge text-bg-secondary"><?php echo strtoupper($n['fiscal_status']); ?></span></td><td><details><summary class="btn btn-sm btn-outline-primary rounded-pill">EDITAR</summary><form method="POST" class="row g-2 mt-2" style="min-width:650px"><input type="hidden" name="venda_id" value="<?php echo $n['venda']; ?>"><div class="col"><input class="form-control" name="numero" placeholder="Número" value="<?php echo htmlspecialchars($n['numero']??''); ?>"></div><div class="col"><input class="form-control" name="serie" placeholder="Série" value="<?php echo htmlspecialchars($n['serie']??''); ?>"></div><div class="col-12"><input class="form-control" name="chave_acesso" placeholder="Chave de acesso" value="<?php echo htmlspecialchars($n['chave_acesso']??''); ?>"></div><div class="col"><input class="form-control" name="protocolo" placeholder="Protocolo" value="<?php echo htmlspecialchars($n['protocolo']??''); ?>"></div><div class="col"><select class="form-select" name="status"><?php foreach(array('pendente','emitida','cancelada','erro') as $st){ ?><option <?php echo $n['fiscal_status']===$st?'selected':''; ?>><?php echo $st; ?></option><?php } ?></select></div><div class="col-12"><input class="form-control" name="observacao" placeholder="Observação"></div><div class="col-12"><button class="btn btn-primary btn-sm rounded-pill">SALVAR</button></div></form></details></td></tr><?php } ?></tbody></table></div></section></main><?php recursosRodape(); ?></body></html>